/* vNN.xx, UI REDESIGN ui5q2k (his #50, from the AAA judge of the shop shot): THE SHOP FILLS ITS WINDOW. The counter (the grid and the
   paper card) was capped at 78 percent of the screen height and sat at the top, so the lower 40 percent of the window, under both,
   was empty. In the shop, craft and hire tabs the grid frame now runs down to the footer line with larger tiles (at least 210px,
   not 170); the paper card keeps the height of what it holds, as on the Mainframe, so no blank paper fills the gap. */
#root #tradermodal .vend{ flex:1 1 auto; max-height:none; }
#root #tradermodal .vend > .vdet{ align-self:flex-start; }
#root #tradermodal .vendgrid{ grid-template-columns:repeat(auto-fill,minmax(210px,1fr)); }
/* vNN.xx, UI REDESIGN ui5q1c (his #50, from the AAA judge

check:
{v:'VER',what:'his #50 (UI redesign ui5q2k): in the shop the item grid runs down to the foot of its pane (no empty lower band) and the paper card keeps the height of what it holds',
 run:function(){
   if(!(window.__station&&window.__hubEnter)) return 'SKIP: this fixture cannot walk the Undercroft';
   var bad=[], d=null, q, i, tp, gap;
   try{
     __topClear(); __hubEnter(); __station('trader','KeyE');
     q=document.querySelectorAll('#tradermodal .vendgrid');
     for(i=0;i<q.length;i++) if(q[i].getClientRects().length){ d=q[i]; break; }
     if(!d) return 'SKIP: the shop drew no grid';
     tp=d.closest('.tpane')||d.parentNode.parentNode;
     gap=tp.getBoundingClientRect().bottom-d.getBoundingClientRect().bottom;
     if(gap>48) bad.push('the shop grid stops '+Math.round(gap)+'px above the foot of its pane');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ __topClear(); }catch(_c){} }
   return bad.length?bad.join('; '):null; }},
